"""Standalone Beeline agent, generated by tools/bundle_agent.py."""

# --- agent_core/__init__.py ---
"""Beeline campaign agent core: priors -> Bayesian posterior -> pilots -> allocation."""

# --- agent_core/priors.py ---
"""Priors on the base effect (ratio at channel multiplier 1.0) per (cell, target).

cell = (current_tariff, arpu_segment). The source is pluggable: call
set_prior_source(fn) with fn(cell, target) -> (mean, sd) to replace the default.
"""

WEAK_MEAN = 0.0
WEAK_SD = 0.1


def weak_prior(cell, target):
    return WEAK_MEAN, WEAK_SD


_source = weak_prior


def set_prior_source(fn):
    global _source
    _source = fn if fn is not None else weak_prior


def get_prior(cell, target):
    return _source(cell, target)

# --- agent_core/priors_history.py ---
"""History prior on the base effect per (cell, target), from data/change_tariff.csv.

Base effect = relative ARPU change x conversion at channel multiplier 1.0.
History is only a hint (judge effects differ from it), so the mean is shrunk
toward 0 and the sd is kept wide. Definitions: docs/PRIORS.md.

Plug in:  set_prior_source(priors_history.get_prior)
"""

import logging
import math
from pathlib import Path

import pandas as pd

logger = logging.getLogger(__name__)

DATA_PATH = Path(__file__).resolve().parent / "data" / "change_tariff.csv"

LOW_MAX = 1000.0      # arpu_segment thresholds from the case guide (ARPU_3m_avg)
MID_MAX = 5000.0
MIN_PREV_ARPU = 50.0  # below this the relative change is dominated by the tiny denominator
PCT_CAP = 5.0         # relative change clipped to [-1, PCT_CAP]; tail beyond ~p95 is noise
SHRINK_K = 30.0       # pseudo-count: mean is scaled by n / (n + SHRINK_K)
SD_FLOOR = 0.05
UNSEEN_SD = 0.1       # no history for (cell, target): same as priors.weak_prior


def arpu_segment(arpu):
    if arpu < LOW_MAX:
        return "LOW"
    if arpu <= MID_MAX:
        return "MID"
    return "HIGH"


def load_table(path=None):
    """{(from_tariff, arpu_segment, to_tariff): {n, mean, std, conv}}; {} if unreadable.

    Tries `path` (or the module-relative DATA_PATH), then data/ under the current
    working directory. An empty table is logged loudly: without it every prior is
    (0, 0.1) and the explorer falls back to price-based upsell targets.
    """
    candidates = [Path(path)] if path is not None else [DATA_PATH, Path.cwd() / "data" / "change_tariff.csv"]
    df = None
    for candidate in candidates:
        try:
            df = pd.read_csv(candidate, usecols=["AVG_ARPU_PREV_3M", "AVG_ARPU_NEXT_3M",
                                                 "tariff_plan_code_from", "tariff_plan_code_to"])
            break
        except (OSError, ValueError):
            continue
    if df is None:
        logger.warning("history prior unavailable: none of %s readable; using weak priors",
                       [str(c) for c in candidates])
        return {}

    df = df[df["AVG_ARPU_PREV_3M"] >= MIN_PREV_ARPU].copy()
    if df.empty:
        return {}
    df["segment"] = df["AVG_ARPU_PREV_3M"].map(arpu_segment)
    df["pct"] = ((df["AVG_ARPU_NEXT_3M"] - df["AVG_ARPU_PREV_3M"])
                 / df["AVG_ARPU_PREV_3M"]).clip(-1.0, PCT_CAP)

    keys = ["tariff_plan_code_from", "segment", "tariff_plan_code_to"]
    g = df.groupby(keys).agg(n=("pct", "size"), mean=("pct", "mean"),
                             std=("pct", "std")).reset_index()
    # Conversion proxy: share of switchers from (from, segment) that went to this
    # target, Laplace-smoothed over all targets seen in history.
    n_targets = df["tariff_plan_code_to"].nunique()
    total = g.groupby(["tariff_plan_code_from", "segment"])["n"].transform("sum")
    g["conv"] = (g["n"] + 1) / (total + n_targets)

    return {
        (r.tariff_plan_code_from, r.segment, r.tariff_plan_code_to): {
            "n": int(r.n),
            "mean": float(r.mean),
            "std": 0.0 if pd.isna(r.std) else float(r.std),
            "conv": float(r.conv),
        }
        for r in g.itertuples(index=False)
    }


def prior_from_stats(stats):
    """(mean, sd) of the base effect for one history row of load_table()."""
    n, conv = stats["n"], stats["conv"]
    raw = conv * stats["mean"]
    mean = raw * n / (n + SHRINK_K)
    se = conv * stats["std"] / math.sqrt(n)
    # Judge effects differ from history: uncertainty at least the size of the effect itself.
    sd = max(SD_FLOOR, math.sqrt(se * se + raw * raw))
    return mean, sd


def make_prior_source(table):
    def source(cell, target):
        stats = table.get((cell[0], cell[1], target))
        if stats is None:
            return 0.0, UNSEEN_SD
        return prior_from_stats(stats)
    return source


_default = None


def get_history_prior(cell, target):
    global _default
    if _default is None:
        _default = make_prior_source(load_table())
    return _default(cell, target)

# --- agent_core/cells.py ---
"""Audience cells = (current_tariff, arpu_segment) with size and mean predicted ARPU."""


def build_cells(profile):
    g = (profile.groupby(["current_tariff", "arpu_segment"], observed=True)
         .agg(size=("ID_NUMBER", "size"), arpu=("predicted_arpu", "mean"))
         .reset_index())
    return {
        (r.current_tariff, r.arpu_segment): {"size": int(r.size), "arpu": float(r.arpu)}
        for r in g.itertuples(index=False)
    }

# --- agent_core/bayes.py ---
"""Normal-normal posterior on the base effect per (cell, target).

A pilot on channel ch observes ratio = base * mult_ch + N(0, 0.804 / sqrt(n)),
so in base-effect units: obs = ratio / mult, sd = 0.804 / (sqrt(n) * mult).
"""

import math


PILOT_NOISE = 0.804


class Posterior:
    def __init__(self):
        self._state = {}  # (cell, target) -> (mean, var)
        self.n_obs = {}   # (cell, target) -> pilots observed
        self.n_total = {} # (cell, target) -> customers observed over all pilots
        self._pilot = {}  # (cell, target) -> (sum obs * precision, sum precision), prior ignored

    def get(self, cell, target):
        key = (cell, target)
        if key not in self._state:
            mean, sd = get_prior(cell, target)
            self._state[key] = (mean, sd * sd)
        mean, var = self._state[key]
        return mean, math.sqrt(var)

    def update(self, cell, target, observed_ratio, n, mult):
        mean, sd = self.get(cell, target)
        obs = observed_ratio / mult
        obs_var = (PILOT_NOISE / (math.sqrt(n) * mult)) ** 2
        prec = 1.0 / (sd * sd) + 1.0 / obs_var
        new_var = 1.0 / prec
        new_mean = new_var * (mean / (sd * sd) + obs / obs_var)
        self._state[(cell, target)] = (new_mean, new_var)
        self.n_obs[(cell, target)] = self.n_obs.get((cell, target), 0) + 1
        self.n_total[(cell, target)] = self.n_total.get((cell, target), 0) + n
        wsum, psum = self._pilot.get((cell, target), (0.0, 0.0))
        self._pilot[(cell, target)] = (wsum + obs / obs_var, psum + 1.0 / obs_var)
        return new_mean, math.sqrt(new_var)

    def lcb(self, cell, target, k=1.0):
        mean, sd = self.get(cell, target)
        return mean - k * sd

    def ucb(self, cell, target, k=1.0):
        mean, sd = self.get(cell, target)
        return mean + k * sd

    def confirmed_enough(self, cell, target, min_pilots=2, min_n=300):
        key = (cell, target)
        return self.n_obs.get(key, 0) >= min_pilots or self.n_total.get(key, 0) >= min_n

    def pilot_only(self, cell, target):
        """Pooled pilot estimate of the base effect, prior ignored; None if never piloted."""
        wsum, psum = self._pilot.get((cell, target), (0.0, 0.0))
        if psum <= 0:
            return None
        return wsum / psum, math.sqrt(1.0 / psum)

# --- agent_core/planner.py ---
"""Final campaigns: greedy allocation of confident-positive cells under reach/money caps."""

from itertools import product

MAX_PER_CAMPAIGN = 5000
MAX_CAMPAIGNS = 10
FINAL_K = 1.5  # final only if mean - FINAL_K * sd > 0


# Sub-segment splits (("data_segment", "call_segment")) are off: on stress_eval they
# amplified a false positive (39/50 positive vs 40/50 without, same worst case).
SPLIT_COLUMNS = ()

# Legal filter values of the scorer (scoring_core.FILTER_VALUES), for schema-valid
# campaigns that deliberately match nobody.
SEGMENT_VALUES = {
    "filter_arpu_segment": ("LOW", "MID", "HIGH"),
    "filter_data_segment": ("NON_USER", "LITE", "HEAVY"),
    "filter_call_segment": ("LOW", "MEDIUM", "HIGH"),
}


def _other_tariff(tariffs, tariff):
    return next((t for t in tariffs if t != tariff), tariffs[0])


def zero_customer_campaign(env):
    """Schema-valid push campaign whose legal filters match no customer; None if impossible."""
    profile = env.customer_profile
    tariffs = list(env.tariffs["tariff_plan_code"])
    keys = ["current_tariff", "arpu_segment", "data_segment", "call_segment"]
    counts = profile.groupby(keys, observed=True).size() if len(profile) else None
    for tariff in tariffs:
        for arpu in SEGMENT_VALUES["filter_arpu_segment"]:
            for data in SEGMENT_VALUES["filter_data_segment"]:
                for call in SEGMENT_VALUES["filter_call_segment"]:
                    if counts is None or counts.get((tariff, arpu, data, call), 0) == 0:
                        return {
                            "campaign_name": "no_contact_fallback",
                            "filter_current_tariff": tariff,
                            "filter_arpu_segment": arpu,
                            "filter_data_segment": data,
                            "filter_call_segment": call,
                            "target_tariff": _other_tariff(tariffs, tariff),
                            "channel": "push",
                        }
    return None


def safety_campaign(env):
    """One valid campaign that costs nothing: matches nobody if possible, else the
    globally smallest slice on push. Never raises."""
    try:
        campaign = zero_customer_campaign(env)
        if campaign is not None:
            return campaign
    except Exception:  # noqa: BLE001 - keep falling back
        pass
    tariffs = list(env.tariffs["tariff_plan_code"])
    try:
        profile = env.customer_profile
        keys = ["current_tariff", "arpu_segment", "data_segment", "call_segment"]
        tariff, arpu, data, call = profile.groupby(keys, observed=True).size().idxmin()
        return {
            "campaign_name": "smallest_slice_fallback",
            "filter_current_tariff": tariff, "filter_arpu_segment": arpu,
            "filter_data_segment": data, "filter_call_segment": call,
            "target_tariff": _other_tariff(tariffs, tariff), "channel": "push",
        }
    except Exception:  # noqa: BLE001
        return {"campaign_name": "safety_net", "filter_arpu_segment": "LOW",
                "filter_data_segment": "NON_USER", "filter_call_segment": "HIGH",
                "target_tariff": tariffs[0], "channel": "push"}


def _channel_options(base_mean, arpu, channels):
    """Expected net per contact on every channel for a given base effect."""
    return {ch: base_mean * c["conversion_multiplier"] * arpu - c["cost_per_contact"]
            for ch, c in channels.items()}


def _contacts(size, cost, reach_left, money_left):
    n = min(size, MAX_PER_CAMPAIGN, reach_left)
    if cost > 0:
        n = min(n, int(money_left // cost))
    return max(n, 0)


def _best_assignment(parts, base_mean, channels, reach_left, money_left):
    """Pick a channel (or none) for every disjoint part; maximise expected total net.

    parts: [(filters, arpu_cumsum)] with ARPU sorted by ID_NUMBER, because scoring
    truncates each campaign to its lowest IDs. Parts are allocated in the order of
    their net per contact, which is also the order they are returned in.
    """
    best = (0.0, [])
    for choice in product([None] + list(channels), repeat=len(parts)):
        reach, money = reach_left, money_left
        picked = []
        for (filters, cums), ch in zip(parts, choice):
            if ch is None:
                continue
            c = channels[ch]
            pc = base_mean * c["conversion_multiplier"] * cums[-1] / len(cums) - c["cost_per_contact"]
            picked.append((pc, filters, cums, ch))
        picked.sort(key=lambda x: x[0], reverse=True)
        total, plan = 0.0, []
        for _, filters, cums, ch in picked:
            cost = channels[ch]["cost_per_contact"]
            n = _contacts(len(cums), cost, reach, money)
            if n <= 0:
                continue
            net = base_mean * channels[ch]["conversion_multiplier"] * cums[n - 1] - n * cost
            if net <= 0:
                continue
            reach -= n
            money -= n * cost
            total += net
            plan.append((filters, ch, n, net))
        if total > best[0]:
            best = (total, plan)
    return best


class Planner:
    def __init__(self, env, cells, posterior, pilot_log):
        self.env = env
        self.cells = cells
        self.post = posterior
        self.pilot_log = pilot_log

    def _tested(self):
        return {((p["current_tariff"], p["arpu_segment"]), p["target_tariff"])
                for p in self.pilot_log}

    def qualifying(self):
        """Per cell: the confirmed target with LCB > 0 and the highest posterior mean."""
        best = {}
        for cell, target in sorted(self._tested()):
            mean, sd = self.post.get(cell, target)
            if not self.post.confirmed_enough(cell, target) or mean - FINAL_K * sd <= 0:
                continue
            if cell not in best or mean > best[cell][1]:
                best[cell] = (target, mean)
        return best

    def _rank_value(self, cell, mean, best_pc):
        """Allocation order of qualifying cells: best expected net per contact."""
        return best_pc

    def _parts(self, cell, column):
        """Disjoint sub-segments of a cell ([whole cell] when column is None)."""
        profile = self.env.customer_profile
        sub = profile[(profile["current_tariff"] == cell[0])
                      & (profile["arpu_segment"] == cell[1])].sort_values("ID_NUMBER")
        groups = [({}, sub)] if column is None else [
            ({f"filter_{column}": value}, g) for value, g in sub.groupby(column, observed=True)]
        return [(filters, g["predicted_arpu"].cumsum().to_numpy())
                for filters, g in groups if len(g)]

    def plan(self):
        channels = self.env.channels
        # public counters already include every pilot, also ones run before this act()
        reach_left, money_left = self.env.remaining_contacts, self.env.remaining_budget

        options = []
        for cell, (target, mean) in sorted(self.qualifying().items()):
            per_contact = _channel_options(mean, self.cells[cell]["arpu"], channels)
            best_pc = max(per_contact.values())
            if best_pc > 0:
                options.append((self._rank_value(cell, mean, best_pc), cell, target, mean))
        options.sort(key=lambda x: x[0], reverse=True)

        campaigns = []
        for _, cell, target, mean in options:
            if len(campaigns) >= MAX_CAMPAIGNS or reach_left <= 0:
                break
            # whole cell vs disjoint splits; a split wins only if expected total net improves
            best = (0.0, [])
            for column in (None,) + SPLIT_COLUMNS:
                parts = self._parts(cell, column)
                if len(campaigns) + len(parts) > MAX_CAMPAIGNS:
                    continue
                cand = _best_assignment(parts, mean, channels, reach_left, money_left)
                if cand[0] > best[0]:
                    best = cand
            for filters, ch, n, _ in best[1]:
                reach_left -= n
                money_left -= n * channels[ch]["cost_per_contact"]
                suffix = "_".join(str(v) for v in filters.values())
                campaigns.append({
                    "campaign_name": "_".join(x for x in (cell[0], cell[1], suffix, "to", target, ch) if x),
                    "filter_current_tariff": cell[0],
                    "filter_arpu_segment": cell[1],
                    **filters,
                    "target_tariff": target,
                    "channel": ch,
                })

        if not campaigns:
            campaigns = [self._fallback()]
        return campaigns

    def _smallest_slice(self, cell):
        """Smallest (data_segment, call_segment) slice of a cell: filters and its ARPU sum."""
        profile = self.env.customer_profile
        sub = profile[(profile["current_tariff"] == cell[0])
                      & (profile["arpu_segment"] == cell[1])]
        if not len(sub):
            return {}, 0.0
        g = sub.groupby(["data_segment", "call_segment"], observed=True)["predicted_arpu"]
        sizes = g.size()
        data, call = sizes.idxmin()
        return ({"filter_data_segment": data, "filter_call_segment": call},
                float(g.sum()[(data, call)]))

    def _fallback(self):
        """Nothing passed the gate. Best posterior mean > 0: push on the smallest slice of
        that arm's cell. Otherwise (or nothing tested / empty audience): a schema-valid
        campaign that contacts nobody, so the mandatory campaign costs nothing."""
        tested = sorted(self._tested())
        if not self.cells or not tested:
            return safety_campaign(self.env)
        cell, target = max(tested, key=lambda ct: self.post.get(*ct)[0])
        if self.post.get(cell, target)[0] <= 0:
            return safety_campaign(self.env)
        filters, _ = self._smallest_slice(cell)
        return {
            "campaign_name": f"fallback_{cell[0]}_{cell[1]}_to_{target}_push",
            "filter_current_tariff": cell[0],
            "filter_arpu_segment": cell[1],
            **filters,
            "target_tariff": target,
            "channel": "push",
        }

# --- agent_core/llm_advisor.py ---
"""Optional LLM strategist with guardrails.

Active only when AGENT_USE_LLM=1 and OPENAI_API_KEY are both set (a key alone does
nothing, so a machine with a key still runs fully deterministically). The model sees our posterior table and may:
  * reorder which of OUR top-6 open arms get confirmed first (no new arms);
  * flag arms it finds suspicious (logged, passed to the final review);
  * remove final campaigns (never add or edit them, never remove all of them).
Every call: temperature 0, JSON schema output, a hard 20 s wall-clock deadline covering
the whole request and body read (the worker thread is abandoned on expiry), at most MAX_CALLS per run,
and no new call once TIME_BUDGET_S seconds have been spent in calls in total.
Models that only accept the default temperature (the API rejects 0 with
param "temperature") are retried once without it; that choice is logged and kept.
Any error, timeout or invalid answer -> our deterministic decision stands.
Every decision (accepted, rejected or failed) is appended to self.log and logged.
"""

import json
import logging
import os
import threading
import time
import urllib.error
import urllib.request

logger = logging.getLogger(__name__)

DEFAULT_MODEL = "gpt-5.6-luna"
DEFAULT_BASE_URL = "https://api.openai.com/v1"
TIMEOUT_S = 20
MAX_CALLS = 3
TIME_BUDGET_S = 90  # cumulative wall time in LLM calls per run; further calls are skipped
TOP_K = 6

SYSTEM_PROMPT = (
    "You advise a telecom tariff-migration campaign agent. Each arm is "
    "(current_tariff, arpu_segment) -> target_tariff. 'base_mean'/'base_sd' is our Bayesian "
    "posterior of the relative ARPU effect at channel multiplier 1.0 (prior from history, "
    "updated by noisy pilots, pilot noise sd = 0.804/sqrt(n)/multiplier). Large effects from a "
    "single small pilot, or a posterior far from its prior, are typical winner's-curse signs. "
    "Answer only with JSON matching the schema."
)

RANK_SCHEMA = {
    "type": "object",
    "properties": {
        "order": {"type": "array", "items": {"type": "string"}},
        "suspicious": {"type": "array", "items": {"type": "string"}},
        "reason": {"type": "string"},
    },
    "required": ["order", "suspicious", "reason"],
    "additionalProperties": False,
}

REVIEW_SCHEMA = {
    "type": "object",
    "properties": {
        "remove": {"type": "array", "items": {"type": "string"}},
        "reason": {"type": "string"},
    },
    "required": ["remove", "reason"],
    "additionalProperties": False,
}


def arm_id(cell, target):
    return f"{cell[0]}|{cell[1]}|{target}"


def _str_list(answer, key):
    value = answer.get(key)
    return [v for v in value if isinstance(v, str)] if isinstance(value, list) else []


def _call_with_deadline(fn, timeout):
    """Run fn() in a daemon thread; give up (TimeoutError) after `timeout` seconds."""
    outcome = {}

    def worker():
        try:
            outcome["value"] = fn()
        except BaseException as e:  # noqa: BLE001 - re-raised in the caller
            outcome["error"] = e

    thread = threading.Thread(target=worker, daemon=True)
    thread.start()
    thread.join(timeout)
    if thread.is_alive():
        raise TimeoutError(f"LLM call exceeded {timeout}s wall clock; abandoned")
    if "error" in outcome:
        raise outcome["error"]
    return outcome["value"]


class TemperatureUnsupported(Exception):
    """The model rejected temperature=0 (only its default is allowed)."""


def _post(body):
    base = (os.environ.get("OPENAI_BASE_URL") or DEFAULT_BASE_URL).rstrip("/")
    req = urllib.request.Request(
        f"{base}/chat/completions",
        data=json.dumps(body).encode("utf-8"),
        headers={"Content-Type": "application/json",
                 "Authorization": f"Bearer {os.environ['OPENAI_API_KEY']}"},
    )
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT_S) as resp:
            payload = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        detail = e.read().decode("utf-8", "replace")
        try:
            error = json.loads(detail).get("error") or {}
        except ValueError:
            error = {}
        if e.code == 400 and error.get("param") == "temperature":
            raise TemperatureUnsupported(error.get("message", "")) from e
        raise RuntimeError(f"HTTP {e.code}: {error.get('message') or detail[:300]}") from e
    return json.loads(payload["choices"][0]["message"]["content"])


def _http_body(messages, schema_name, schema, temperature):
    body = {
        "model": os.environ.get("OPENAI_MODEL") or DEFAULT_MODEL,
        "messages": messages,
        "response_format": {"type": "json_schema",
                            "json_schema": {"name": schema_name, "strict": True, "schema": schema}},
    }
    if temperature:
        body["temperature"] = 0
    return body


class LLMAdvisor:
    def __init__(self, transport=None, clock=time.monotonic):
        self.enabled = transport is not None or (
            os.environ.get("AGENT_USE_LLM") == "1" and bool(os.environ.get("OPENAI_API_KEY")))
        self._transport = transport or self._http_transport
        self._clock = clock
        self._temperature_zero = True
        self.calls = 0
        self.elapsed = 0.0
        self.suspicious = []
        self.log = []

    def _http_transport(self, messages, schema_name, schema):
        """POST to chat completions; drop temperature=0 once if the model rejects it."""
        try:
            return _post(_http_body(messages, schema_name, schema, self._temperature_zero))
        except TemperatureUnsupported as e:
            if not self._temperature_zero:
                raise
            self._temperature_zero = False
            self._record(schema_name, status="temperature_default",
                         reason=f"model rejected temperature=0, using its default: {e}")
            return _post(_http_body(messages, schema_name, schema, False))

    def _record(self, step, **entry):
        entry = {"step": step, **entry}
        self.log.append(entry)
        logger.info("llm_advisor %s", json.dumps(entry, ensure_ascii=False, default=str))

    def _ask(self, step, payload, schema_name, schema):
        if not self.enabled:
            return None
        if self.calls >= MAX_CALLS:
            self._record(step, status="skipped", reason="call limit reached")
            return None
        if self.elapsed >= TIME_BUDGET_S:
            self._record(step, status="skipped",
                         reason=f"time budget spent: {self.elapsed:.1f}s >= {TIME_BUDGET_S}s")
            return None
        self.calls += 1
        messages = [{"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}]
        started = self._clock()
        try:
            answer = _call_with_deadline(
                lambda: self._transport(messages, schema_name, schema), TIMEOUT_S)
            if not isinstance(answer, dict):
                raise ValueError("answer is not a JSON object")
            return answer
        except Exception as e:  # network, timeout, HTTP error, bad JSON: fall back
            self._record(step, status="failed", error=f"{type(e).__name__}: {e}")
            return None
        finally:
            self.elapsed += self._clock() - started

    def rank_confirmations(self, arms, table):
        """arms: our open arms in our order. Returns the new order (only top-6 reordered)."""
        top = arms[:TOP_K]
        ids = [arm_id(c, t) for c, t in top]
        answer = self._ask("rank_confirmations",
                           {"task": "Order these arm ids by which to confirm first with a "
                                    "200-customer pilot; flag suspicious arm ids.",
                            "candidates": ids, "posterior_table": table},
                           "rank_confirmations", RANK_SCHEMA)
        if answer is None:
            return arms
        order = _str_list(answer, "order")
        suspicious = _str_list(answer, "suspicious")
        valid = [i for i in dict.fromkeys(order) if i in ids]  # only our top-6, no duplicates
        valid += [i for i in ids if i not in valid]            # nothing may be dropped
        by_id = dict(zip(ids, top))
        self.suspicious = suspicious
        self._record("rank_confirmations", status="applied", ours=ids, llm=order,
                     applied=valid, ignored=[i for i in order if i not in ids],
                     suspicious=self.suspicious, reason=answer.get("reason"))
        return [by_id[i] for i in valid] + arms[TOP_K:]

    def review_finals(self, campaigns, table):
        """May only remove campaigns by name; never adds, edits, or empties the list."""
        names = [c["campaign_name"] for c in campaigns]
        answer = self._ask("review_finals",
                           {"task": "Return names of final campaigns to REMOVE because their "
                                    "evidence looks unreliable; empty list keeps all.",
                            "campaigns": [{**c, "arm": arm_id((c.get("filter_current_tariff"),
                                                                c.get("filter_arpu_segment")),
                                                               c.get("target_tariff"))}
                                          for c in campaigns],
                            "suspicious_arms": self.suspicious,
                            "posterior_table": table},
                           "review_finals", REVIEW_SCHEMA)
        if answer is None:
            return campaigns
        remove = _str_list(answer, "remove")
        drop = {n for n in remove if n in names}
        if drop and len(drop) == len(names):
            self._record("review_finals", status="rejected", llm=remove,
                         reason="would remove every campaign", llm_reason=answer.get("reason"))
            return campaigns
        kept = [c for c in campaigns if c["campaign_name"] not in drop]
        self._record("review_finals", status="applied", llm=remove, removed=sorted(drop),
                     ignored=[n for n in remove if n not in names], reason=answer.get("reason"))
        return kept

# --- agent_core/explorer.py ---
"""Pilot phase: pick single-cell sms pilots, feed results into the posterior."""


MIN_CELL_SIZE = 300
MIN_PILOT_CELL = 10  # admitted only when no cell reaches MIN_CELL_SIZE (env minimum pilot)
ROUND1_PILOTS = 10
ROUND1_PER_CELL = 2
ROUND1_N = 150
ROUND2_N = 200
MAX_PILOTS_PER_ARM = 2  # screen + one confirmation; no re-piloting until lucky
# Adaptive stop: skip round 2 when no arm looks positive on both posterior and pilots
# alone; end round 2 as soon as one arm passes the launch gate. Off: on stress_eval it
# kept 40/50 but did not improve the worst run (-227,816, lost in round-1 pilots).
ADAPTIVE_STOP = False
PILOT_CHANNEL = "sms"
# The effect ratio depends only on the (tariff, arpu_segment) cell, so a pilot on any
# data/call slice of the cell observes the same ratio. Pilot on the slice with the lowest
# mean predicted ARPU (enough customers for n): same signal, smaller loss if negative.
CHEAP_SLICE_PILOTS = True
SLICE_COLUMNS = ("data_segment", "call_segment")


class Explorer:
    def __init__(self, env, cells, posterior, advisor=None):
        self.env = env
        self.cells = cells
        self.post = posterior
        self.advisor = advisor
        self.log = []  # our own record of every pilot incl. filters

    def _upsell_targets(self, tariff):
        """Targets priced above `tariff`, nearest first; [] if prices are unknown."""
        if "price_tariff" not in self.env.tariffs.columns:
            return []
        price = dict(zip(self.env.tariffs["tariff_plan_code"], self.env.tariffs["price_tariff"]))
        current = price.get(tariff)
        if current is None:
            return []
        higher = [t for t, p in price.items() if p > current]
        return sorted(higher, key=lambda t: (price[t] - current, t))

    def candidates(self):
        """Round-1 arms: cells by value (size x mean ARPU); per cell the targets with a
        positive prior mean, topped up with the nearest higher-priced tariffs (upsell) when
        the prior has nothing positive to say (e.g. no history table)."""
        targets = list(self.env.tariffs["tariff_plan_code"])
        big = self._eligible_cells()
        big.sort(key=lambda c: self.cells[c]["size"] * self.cells[c]["arpu"], reverse=True)
        out = []
        for cell in big:
            positive = [t for t in targets if t != cell[0] and self.post.get(cell, t)[0] > 0]
            ranked = sorted(positive, key=lambda t: self.post.get(cell, t)[0], reverse=True)
            for t in self._upsell_targets(cell[0]):
                if len(ranked) >= ROUND1_PER_CELL:
                    break
                if t not in ranked and self.post.get(cell, t)[0] >= 0:
                    ranked.append(t)
            out.extend((cell, t) for t in ranked[:ROUND1_PER_CELL])
        return out

    def _eligible_cells(self):
        """Cells big enough to pilot: >= MIN_CELL_SIZE, else (tiny audience) >= MIN_PILOT_CELL."""
        big = [c for c, info in self.cells.items() if info["size"] >= MIN_CELL_SIZE]
        if not big:
            big = [c for c, info in self.cells.items() if info["size"] >= MIN_PILOT_CELL]
        return big

    def _pilot_channel(self):
        """sms while a minimum pilot is affordable, otherwise the free channel if any."""
        cost = self.env.channels[PILOT_CHANNEL]["cost_per_contact"]
        if self.env.remaining_budget >= cost * MIN_PILOT_CELL:
            return PILOT_CHANNEL
        free = [ch for ch, c in self.env.channels.items() if c["cost_per_contact"] == 0]
        return free[0] if free else PILOT_CHANNEL

    def _can_pilot(self, n):
        cost = self.env.channels[self._pilot_channel()]["cost_per_contact"]
        return (self.env.pilots_left > 0 and self.env.remaining_contacts >= MIN_PILOT_CELL
                and self.env.remaining_budget >= cost * min(n, MIN_PILOT_CELL))

    def _cheapest_slice(self, cell, n):
        """{filter_<column>: value} of the lowest-mean-ARPU slice with >= n customers, or {}."""
        profile = self.env.customer_profile
        sub = profile[(profile["current_tariff"] == cell[0])
                      & (profile["arpu_segment"] == cell[1])]
        best = None
        for column in SLICE_COLUMNS:
            g = sub.groupby(column, observed=True)["predicted_arpu"].agg(["size", "mean"])
            for value, row in g[g["size"] >= n].iterrows():
                if best is None or row["mean"] < best[0]:
                    best = (row["mean"], {f"filter_{column}": value})
        return best[1] if best else {}

    def pilot(self, cell, target, n):
        tariff, segment = cell
        channel = self._pilot_channel()
        slice_filter = self._cheapest_slice(cell, n) if CHEAP_SLICE_PILOTS else {}
        try:
            res = self.env.run_pilot(target_tariff=target, channel=channel,
                                     n_customers=n, filter_current_tariff=tariff,
                                     filter_arpu_segment=segment, **slice_filter)
        except (RuntimeError, ValueError):
            return None
        mult = self.env.channels[channel]["conversion_multiplier"]
        mean, sd = self.post.update(cell, target, res["observed_lift_ratio"],
                                    res["n_customers"], mult)
        self.log.append({
            "current_tariff": tariff, "arpu_segment": segment, "target_tariff": target,
            "slice": slice_filter, "channel": channel, "n": res["n_customers"], "cost": res["cost"],
            "observed_ratio": res["observed_lift_ratio"], "post_mean": mean, "post_sd": sd,
        })
        return res

    def _passes_gate(self, cell, target):
        mean, sd = self.post.get(cell, target)
        return self.post.confirmed_enough(cell, target) and mean - FINAL_K * sd > 0

    def _any_promising(self, tested):
        """Some arm with posterior mean > 0 AND pilot-only mean > 0."""
        for tariff, segment, target in sorted(tested):
            cell = (tariff, segment)
            pilot = self.post.pilot_only(cell, target)
            if self.post.get(cell, target)[0] > 0 and pilot is not None and pilot[0] > 0:
                return True
        return False

    def _open_leaders(self, tested):
        """Arms worth confirming, best first: mean > 0, not capped, not yet through the gate."""
        out = []
        for tariff, segment, target in sorted(tested):
            cell = (tariff, segment)
            mean, sd = self.post.get(cell, target)
            if mean <= 0 or self.post.n_obs.get((cell, target), 0) >= MAX_PILOTS_PER_ARM:
                continue
            if self._passes_gate(cell, target):
                continue
            info = self.cells[cell]
            out.append((mean * info["size"] * info["arpu"], cell, target))
        out.sort(key=lambda x: x[0], reverse=True)
        return out

    def posterior_table(self):
        """Every piloted arm with prior, posterior and evidence, for the LLM advisor."""
        rows = []
        for cell, target in sorted({((p["current_tariff"], p["arpu_segment"]), p["target_tariff"])
                                    for p in self.log}):
            prior_mean, prior_sd = get_prior(cell, target)
            mean, sd = self.post.get(cell, target)
            rows.append({
                "arm": arm_id(cell, target),
                "cell_size": self.cells[cell]["size"], "cell_mean_arpu": round(self.cells[cell]["arpu"], 1),
                "prior_mean": round(prior_mean, 4), "prior_sd": round(prior_sd, 4),
                "base_mean": round(mean, 4), "base_sd": round(sd, 4),
                "pilots": self.post.n_obs.get((cell, target), 0),
                "customers": self.post.n_total.get((cell, target), 0),
                "observed_ratios": [round(p["observed_ratio"], 4) for p in self.log
                                    if (p["current_tariff"], p["arpu_segment"]) == cell
                                    and p["target_tariff"] == target],
            })
        return rows

    def run(self):
        # Round 1: cells by value (size x mean ARPU), targets by prior mean / upsell price.
        for cell, target in self.candidates()[:ROUND1_PILOTS]:
            if not self._can_pilot(ROUND1_N):
                break
            self.pilot(cell, target, ROUND1_N)

        # Round 2: confirm round-1 leaders (mean > 0) until they pass or fail the final gate.
        tested = {(p["current_tariff"], p["arpu_segment"], p["target_tariff"]) for p in self.log}
        if ADAPTIVE_STOP and not self._any_promising(tested):
            return self.log
        priority = {}
        if self.advisor is not None and self.advisor.enabled:
            ours = [(cell, target) for _, cell, target in self._open_leaders(tested)]
            ranked = self.advisor.rank_confirmations(ours, self.posterior_table())
            priority = {arm: i for i, arm in enumerate(ranked)}
        while self._can_pilot(ROUND2_N):
            open_leaders = self._open_leaders(tested)
            if not open_leaders:
                break
            open_leaders.sort(key=lambda x: priority.get((x[1], x[2]), len(priority)))
            _, cell, target = open_leaders[0]
            if self.pilot(cell, target, ROUND2_N) is None:
                break
            if ADAPTIVE_STOP and any(self._passes_gate((t, s), g) for t, s, g in sorted(tested)):
                break
        return self.log

# --- agent_core/v4.py ---
"""Policy v4: wide screening, winner's-curse re-check, launch every pilot-positive arm.

Pilots: one target per cell (highest prior mean among higher-priced tariffs, never a
downgrade); the top 10 cells by prior x size x mean ARPU get one sms pilot of 150 on the
cheapest slice; then up to 5 pilots of 200 re-check the top 3 arms by observed ratio.
Finals: every arm with pooled pilot estimate > 0 and posterior mean > 0, ranked by
expected total net, channel and size from the planner economics, no overlapping segments.
"""


V4_ROUND1_PILOTS = 10
V4_RECHECK_ARMS = 3
V4_RECHECK_PILOTS = 5
# Never leave pilots unused: after the re-check, screen the next-best unexplored cells
# (any cell that can host one pilot, i.e. >= ROUND1_N customers) with the remaining pilots.
V4_SCREEN_LEFTOVER = True


class ExplorerV4(Explorer):
    def candidates(self, eligible=None):
        """One upsell target per cell (highest prior mean); cells by prior x size x ARPU."""
        scored = []
        eligible = set(self._eligible_cells()) if eligible is None else set(eligible)
        for cell, info in sorted(self.cells.items()):
            if cell not in eligible:
                continue
            upsell = self._upsell_targets(cell[0])
            if not upsell:
                continue
            target = max(upsell, key=lambda t: (self.post.get(cell, t)[0], -upsell.index(t)))
            prior = self.post.get(cell, target)[0]
            if prior < 0:
                continue
            scored.append((prior * info["size"] * info["arpu"], info["size"] * info["arpu"],
                           cell, target))
        # Positive-prior arms first by prior x value; with no informative prior (e.g. no
        # history table) the nearest upsell of the most valuable cells is still piloted.
        scored.sort(key=lambda x: (x[0] > 0, x[0], x[1]), reverse=True)
        return [(cell, target) for _, _, cell, target in scored]

    def run(self):
        first = {}
        for cell, target in self.candidates()[:V4_ROUND1_PILOTS]:
            if not self._can_pilot(ROUND1_N):
                break
            res = self.pilot(cell, target, ROUND1_N)
            if res is not None:
                first[(cell, target)] = res["observed_lift_ratio"]

        # Winner's-curse check: the top arms by observed ratio get a second look, then
        # the remaining re-check pilots go to the best pooled estimates that stay positive.
        top = sorted((arm for arm, ratio in first.items() if ratio > 0),
                     key=lambda arm: first[arm], reverse=True)[:V4_RECHECK_ARMS]
        rechecks = 0
        for cell, target in top:
            if rechecks >= V4_RECHECK_PILOTS or not self._can_pilot(ROUND2_N):
                break
            if self.pilot(cell, target, ROUND2_N) is not None:
                rechecks += 1
        while rechecks < V4_RECHECK_PILOTS and self._can_pilot(ROUND2_N):
            alive = [(self.post.pilot_only(cell, target)[0], cell, target) for cell, target in top
                     if self.post.pilot_only(cell, target)[0] > 0]
            if not alive:
                break
            _, cell, target = max(alive)
            if self.pilot(cell, target, ROUND2_N) is None:
                break
            rechecks += 1

        if V4_SCREEN_LEFTOVER:
            piloted = {(cell, target) for cell, target in first}
            piloted_cells = {cell for cell, _ in piloted}
            hostable = [c for c, info in self.cells.items()
                        if info["size"] >= ROUND1_N and c not in piloted_cells]
            for cell, target in self.candidates(eligible=hostable):
                if not self._can_pilot(ROUND1_N):
                    break
                self.pilot(cell, target, ROUND1_N)
        return self.log


class PlannerV4(Planner):
    """Launch every arm with pooled pilot estimate > 0 and posterior mean > 0 (optionally
    only the `max_finals` best by expected total net)."""

    def __init__(self, env, cells, posterior, pilot_log, max_finals=None):
        super().__init__(env, cells, posterior, pilot_log)
        self.max_finals = max_finals

    def qualifying(self):
        best = {}
        for cell, target in sorted(self._tested()):
            mean, _ = self.post.get(cell, target)
            pilot = self.post.pilot_only(cell, target)
            if mean <= 0 or pilot is None or pilot[0] <= 0:
                continue
            if cell not in best or mean > best[cell][1]:
                best[cell] = (target, mean)
        if self.max_finals is not None and len(best) > self.max_finals:
            ranked = sorted(best.items(), key=lambda kv: self._rank_value(kv[0], kv[1][1], 0.0),
                            reverse=True)
            best = dict(ranked[:self.max_finals])
        return best

    def _rank_value(self, cell, mean, _best_pc):
        """Expected total net of the whole cell alone, under the full post-pilot budget."""
        reach, money = self.env.remaining_contacts, self.env.remaining_budget
        return _best_assignment(self._parts(cell, None), mean, self.env.channels, reach, money)[0]

# --- agent.py ---
"""Beeline campaign agent: explore with single-cell pilots, exploit confident cells."""

import logging


# "v3": confirmation gate (2 pilots, mean - 1.5 sd > 0). "v4": wide screening, re-check,
# launch every pilot-positive arm (agent_core/v4.py). Benchmarked in docs/BENCHMARK.md.
POLICY = "v4"

logger = logging.getLogger(__name__)


class Agent:
    def __init__(self, policy=None, max_finals=None):
        self.policy = policy or POLICY
        self.max_finals = max_finals  # v4 only: launch at most this many finals

    def act(self, env):
        """Never raises: any failure returns one valid, cost-free push campaign."""
        try:
            return self._act(env)
        except Exception:  # noqa: BLE001 - the judge run must always get campaigns
            logger.exception("agent failed; returning the safety campaign")
            try:
                return [safety_campaign(env)]
            except Exception:  # noqa: BLE001
                return [{"campaign_name": "safety_net", "channel": "push",
                         "target_tariff": env.tariffs["tariff_plan_code"].iloc[0]}]

    def _act(self, env):
        set_prior_source(get_history_prior)
        cells = build_cells(env.customer_profile)
        post = Posterior()
        self.advisor = LLMAdvisor()  # inactive without OPENAI_API_KEY
        if self.policy == "v4":
            explorer = ExplorerV4(env, cells, post, advisor=self.advisor)
            pilot_log = explorer.run()
            planner = PlannerV4(env, cells, post, pilot_log, max_finals=self.max_finals)
        else:
            explorer = Explorer(env, cells, post, advisor=self.advisor)
            pilot_log = explorer.run()
            planner = Planner(env, cells, post, pilot_log)
        self.pilot_log = pilot_log
        campaigns = planner.plan()
        if self.advisor.enabled:
            campaigns = self.advisor.review_finals(campaigns, explorer.posterior_table())
        return campaigns
